    #[test]
    fn arm_is_live_state_and_f9_records_only_an_armed_track() {
        let mut stage = Stage::new();
        assert_eq!(
            drive(&mut stage, &[Key::F9]),
            vec![ApplyOutcome::Refused(Refusal {
                intent: StageIntent::ToggleRecord,
                reason: RefusalReason::Unavailable,
            })]
        );
        assert_eq!(drive(&mut stage, &[Key::A]), vec![ApplyOutcome::Changed]);
        assert!(stage.song.tracks[0].armed);
        assert!(!stage.is_dirty(), "a transient arm dirtied the project");
        assert!(!stage.history.can_undo(), "an arm became an undo step");

        assert_eq!(drive(&mut stage, &[Key::F9]), vec![ApplyOutcome::Changed]);
        assert!(stage.recording());
        assert!(
            stage.song_mode(),
            "track recording did not select the arrangement"
        );
        assert_eq!(
            drive(&mut stage, &[Key::Space]),
            vec![ApplyOutcome::Changed]
        );
        assert!(!stage.recording());
    }

    #[test]
    fn audio_arm_input_and_monitor_are_keyboard_operable_and_safe_during_record() {
        let mut stage = Stage::new();
        assert_eq!(command(&mut stage, Key::T), ApplyOutcome::Changed);
        stage.set_stream(Some(Stream {
            sample_rate: 48_000,
            buffer_frames: 256,
            latency_frames: Some(256),
            inputs: 4,
            outputs: 2,
            backend: "test",
        }));
        assert_eq!(drive(&mut stage, &[Key::I]), vec![ApplyOutcome::Changed]);
        assert_eq!(stage.song.tracks[1].input, TrackInput::Mono(0));
        assert_eq!(
            stage.handle_key(Mods::SHIFT, Key::A),
            Some(ApplyOutcome::Changed)
        );
        assert_eq!(stage.song.tracks[1].monitor.label(), "IN");
        assert_eq!(drive(&mut stage, &[Key::A]), vec![ApplyOutcome::Changed]);
        assert_eq!(
            stage.record_routes(),
            vec![crate::record::RecordRoute {
                track: 1,
                channels: vec![0],
            }]
        );
        assert_eq!(drive(&mut stage, &[Key::F9]), vec![ApplyOutcome::Changed]);
        let before = stage.song.tracks[1].input;
        assert!(matches!(
            drive(&mut stage, &[Key::I]).as_slice(),
            [ApplyOutcome::Refused(Refusal {
                intent: StageIntent::CycleTrackInput { back: false },
                reason: RefusalReason::Unavailable,
            })]
        ));
        assert_eq!(stage.song.tracks[1].input, before);
        let _ = drive(&mut stage, &[Key::Space]);
    }

    #[test]
    fn completed_audio_and_midi_takes_land_in_the_arrangement() {
        let mut audio = Stage::new();
        audio.song.tracks[0].kind = TrackKind::Audio;
        audio.song.tracks[0].blocks.clear();
        audio.commit_recording(
            vec![crate::record::Take {
                track: 0,
                path: std::env::temp_dir().join("stage-recording-test.wav"),
                frames: 48_000,
                channels: 1,
                sample_rate: 48_000,
            }],
            Vec::new(),
            24_000,
            48_000,
            240,
            0,
            48_000,
            Vec::new(),
        );
        let block = audio.song.tracks[0]
            .audio_blocks
            .first()
            .expect("audio take did not land");
        assert!(block.length_ticks > 0);
        assert!(audio.is_dirty());

        let mut midi = Stage::new();
        midi.song.tracks[0].blocks.clear();
        midi.commit_recording(
            Vec::new(),
            vec![crate::record::MidiTake {
                track: 0,
                notes: vec![crate::record::MidiTakeNote {
                    // Observed half a beat after the sound it belongs to.
                    start_sample: 36_000,
                    end_sample: 48_000,
                    pitch: 64,
                    velocity: 101,
                }],
            }],
            0,
            48_000,
            12_000,
            0,
            24_000,
            Vec::new(),
        );
        let block = midi.song.tracks[0]
            .blocks
            .first()
            .expect("MIDI take did not make a block");
        assert_eq!(
            block.start_tick,
            crate::sequencing::TICKS_PER_BEAT,
            "MIDI was not moved back by the shared recording latency"
        );
        let id = block.pattern_id;
        assert_eq!(
            midi.song
                .pattern(id)
                .expect("recorded pattern")
                .trig(0)
                .primary(),
            Some(&crate::sequencing::Note::new(
                64,
                crate::sequencing::TICKS_PER_BEAT / 2,
                101,
            ))
        );
        assert!(midi.is_dirty());
    }

